  `user_mtime` datetime NOT NULL,
  `suppressed` int(11) NOT NULL DEFAULT '0',
  `slug` varchar(255) DEFAULT NULL,
  `is_slug_auto` int(11) DEFAULT '0',
  PRIMARY KEY (`id`),
