INSERT INTO `note` VALUES (17,1,NULL,2,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"A journal and fifteen letters documenting the overland journey of Sarah Wayward Lewis with her husband and family to California in 1849. The Lewis family departed from St. Joseph, Missouri in April, 1849, and the collection contents detail their trip along the Mormon Route, encounters with hostile Native Americans on the Great Plains, privations, hardships, and internal strife among their traveling companions; and their sojourn along the Humboldt and Truckee Rivers prior to their traverse of Donner Pass into the goldfields of California. The correspondence, from Sarah Lewis to her mother, Frances Wayward of Great Barrington, Massachusetts, also provides details about life in a mining camp before Sarah and her children settled in Sacramento in November of the same year.\",\"subnote_guid\":\"f30404a391a7191e74c52c853aa89735\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_ref36\",\"label\":\"Scope and Contents note\"}','admin','admin','2016-08-23 21:04:44','2016-08-23 21:04:44','2016-08-23 21:04:44',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(18,1,NULL,3,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"Grover Allen Wayward was the brother of Theresa Auchincloss, and he served as Associate Director of the Office of Facts and Figures (OFF).\",\"subnote_guid\":\"931159638136fdf2aa0af4310427ae1d\"}],\"type\":\"bioghist\",\"persistent_id\":\"aspace_f84fed81036bbc00be4632dfa3991c8c\",\"label\":\"Biography\"}','admin','admin','2016-08-23 21:04:44','2016-08-23 21:04:44','2016-08-23 21:04:44',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(19,1,NULL,3,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"The Office of Facts and Figures (OFF) was established in October 1941 by President Franklin Roosevelt in order to disseminate information to the American public regarding the war effort. On June 13, 1942, Roosevelt established the Office of War Information, which subsumed the Office of Facts and Figures and included the Committee on War Information Policy, of which Grover Wayward was a member.\",\"subnote_guid\":\"671414113aef9c65c671135d0b939f0f\"}],\"type\":\"bioghist\",\"persistent_id\":\"aspace_085b1777cdf79fbe88d22e6ccb06ba97\",\"label\":\"Administrative Backgroud\"}','admin','admin','2016-08-23 21:04:44','2016-08-23 21:04:44','2016-08-23 21:04:44',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(20,1,NULL,4,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"Compiled by Theresa Auchincloss, these materials contain information about many Wayward family mebers and document some unanswered issues about various individuals. Much of this material appears to be undated, but presumably was accumulated furing the period of Auchincloss\' active interest in family history, from 1954 to hear death in 1963.\",\"subnote_guid\":\"d904367f50c3b5dfcf478380fa885049\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_cbd49ab7acf2a4621ff0d404ba809058\",\"label\":\"Scope and Contents note\"}','admin','admin','2016-08-23 21:04:44','2016-08-23 21:04:44','2016-08-23 21:04:44',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(21,1,NULL,9,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"Arranged chronologically.\",\"subnote_guid\":\"d30718ed3037b3d63aeabfb4c29455f8\"}],\"type\":\"arrangement\",\"persistent_id\":\"aspace_ref42\",\"label\":\"Arrangement note\"}','admin','admin','2016-08-23 21:04:44','2016-08-23 21:04:44','2016-08-23 21:04:44',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(22,1,NULL,10,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"Arranged chronologically.\",\"subnote_guid\":\"ad08fb301c22ec77444de2c4c2673617\"}],\"type\":\"arrangement\",\"persistent_id\":\"aspace_ref44\",\"label\":\"Arrangement note\"}','admin','admin','2016-08-23 21:04:44','2016-08-23 21:04:44','2016-08-23 21:04:44',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(23,1,NULL,11,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"Arranged chronologically.\",\"subnote_guid\":\"687f9f71bfd0ae7918038230c60c5827\"}],\"type\":\"arrangement\",\"persistent_id\":\"aspace_ref46\",\"label\":\"Arrangement note\"}','admin','admin','2016-08-23 21:04:44','2016-08-23 21:04:44','2016-08-23 21:04:44',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(24,1,NULL,13,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"Arranged chronologically.\",\"subnote_guid\":\"2e5ae35de57d76984396b36254222f41\"}],\"type\":\"arrangement\",\"persistent_id\":\"aspace_ref50\",\"label\":\"Arrangement note\"}','admin','admin','2016-08-23 21:04:44','2016-08-23 21:04:44','2016-08-23 21:04:44',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(25,1,NULL,14,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"With unidentified persons releating to public perceptions of German aggression and British suffering duing the Battle of Britain.\",\"subnote_guid\":\"686093618b054cb551f08f7308c9fa00\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_ref52\",\"label\":\"Scope and Contents note\"}','admin','admin','2016-08-23 21:04:44','2016-08-23 21:04:44','2016-08-23 21:04:44',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(26,1,NULL,15,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"Primarily for encouraging different kinds of rationing in order to support the U.S. War effort. The posters were produced by the Office of War Information.\",\"subnote_guid\":\"6ca741550bee38871e14a4c3a8719ab1\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_ref54\",\"label\":\"Scope and Contents note\"}','admin','admin','2016-08-23 21:04:44','2016-08-23 21:04:44','2016-08-23 21:04:44',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(53,1,NULL,36,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"Patrons are required to use the DVD copy in box 4U.\",\"subnote_guid\":\"bb498b6515caf2affa2da200dc47a429\"}],\"type\":\"accessrestrict\",\"persistent_id\":\"aspace_851cd4bf3374bf7bed18993209bc144d\",\"label\":\"Conditions Governing Access\"}','admin','admin','2016-08-23 22:20:07','2016-08-23 22:20:07','2016-08-23 22:20:07',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(54,1,NULL,41,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"Among the photographs, are separate images of Mort Stump with 1) Charles Cutter at a ground-breaking ceremony for the Springfield Public Library, 2) having an ice cream cone with Babe Ruth at a Springfield Fourth of July ceremony, and 3) with Tip O’Neill at a Chamber of Commerce meeting in which Mort was honored for his life-long contributions to the Massachusetts’ business community\",\"subnote_guid\":\"4107dc13a2e272d861c537fce9edd1ac\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_543caf4847dd686da9a2647476c2134c\",\"label\":\"Description\"}','admin','admin','2016-08-23 22:20:07','2016-08-23 22:20:07','2016-08-23 22:20:07',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(55,1,NULL,43,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"in black velvet-covered case, 7.6 x 6.5 cm, stamped on verso in gold lettering: Taber and Boyd Photography / San Francisco\",\"subnote_guid\":\"08a5bdb824a3942baafa06eb241d47b1\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_7d6ffb4f9606f7199a0ec7560acbb599\",\"label\":\"Description\"}','admin','admin','2016-08-23 22:20:07','2016-08-23 22:20:07','2016-08-23 22:20:07',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(67,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_langmaterial\",\"content\":[\"English\"],\"type\":\"langmaterial\",\"persistent_id\":\"b5c560d29341f9462b9473d961a3b06d\"}','admin','admin','2016-08-24 13:24:15','2016-08-24 13:24:15','2016-08-24 13:24:15',NULL,NULL,44,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(68,1,4,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,_binary '{\"jsonmodel_type\":\"note_singlepart\",\"content\":[\"Records of a publishing company established by poets Lewis Warsh and Bernadette Mayer in 1977. Successor to Angel Hair magazine and Angel Hair Books, United Artists published works of contemporary poets and writers, including Ted Berrigan, Clark Coolidge, Alan Ginsberg, Gregory Corso, Robert Creeley, and Bill Berkson. Correspondence with these and other United Artist contributors can be found in the collection. Also included are typescripts of works submitted and materials used for production of United Artists publications.\"],\"type\":\"abstract\",\"persistent_id\":\"aspace_b73112d74aab6dec6337c397a608e948\"}','admin','admin','2016-08-24 13:24:15','2016-08-24 13:24:15','2016-08-24 13:24:15',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(69,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,_binary '{\"jsonmodel_type\":\"note_langmaterial\",\"content\":[\"Collection materials in English\"],\"type\":\"langmaterial\",\"persistent_id\":\"aspace_2cb2b0f2b9d17cc3c19f76ac4b54cf93\"}','admin','admin','2016-08-24 13:24:15','2016-08-24 13:24:15','2016-08-24 13:24:15',NULL,NULL,45,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(70,1,4,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":false,\"jsonmodel_type\":\"note_text\",\"content\":\"Accession Processed in 1988\\n\\n The papers relate to the professional and personal lives of persons associated with United Artists. Many of the artists that Warsh and Mayer dealt with were also friends, and, as a result, the correspondence is often a mix of both literary and private matters. Although a few items date from the middle 1970s, the bulk of the papers date from 1977 to 1983. The collection is organized into three series: 1) CORRESPONDENCE; 2) TYPESCRIPTS, GALLEYS, AND PAGE PROOFS OF UNITED ARTISTS BOOKS; and 3) TYPESCRIPTS SUBMITTED TO THE UNITED ARTISTS MAGAZINE.\\n\\n The largest portion of the collection is comprised of CORRESPONDENCE from various writers to United Artists editors Mayer and Warsh. The series is arranged alphabetically by the correspondent\'s name, and the letters of each correspondent are in chronological order. Unless the correspondent addressed Mayer or Warsh individually, only the name of the writer is listed. \\n\\n The successive stages of production for each book project can be surveyed in the TYPESCRIPTS, GALLEYS, AND PAGE PROOFS OF UNITED ARTISTS BOOKS series. They are arranged alphabetically by the author\'s last name.\\n\\n The TYPESCRIPTS SUBMITTED TO THE UNITED ARTISTS MAGAZINE series contains original typescripts of published and unpublished work. This section includes the work of Gregory Corso, Robert Creeley, and Allen Ginsberg. It is also arranged alphabetically by the name of the author.\",\"subnote_guid\":\"7b53770d503e294a86b46a137c4ae0d9\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_b41b40d463faca69c30171b6bd9d1cb3\",\"label\":\"Scope and Content of Collection\"}','admin','admin','2016-08-24 13:24:15','2016-08-24 13:24:15','2016-08-24 13:24:15',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(71,1,4,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":false,\"jsonmodel_type\":\"note_text\",\"content\":\"Established by Lewis Warsh and Bernadette Mayer in 1977, United Artists press was located in New York City until it went out of business in at the end of the 1980s. Typically, the press published four titles a year, generally with a run of 750 copies each. While they provided a venue for artists who could not publish with mainstream presses, Warsh and Mayer also published established writers such as Allen Ginsberg, Robert Creeley, and Gregory Corso, all of whom had secured contracts with trade publishers.\\n\\n The forerunner of United Artists was Angel Artist (magazine) and Angel Hair Books, a press which Warsh co-founded and co-edited from 1966 to 1977. Many of the contributors to United Artists, such as Ted Berrigan and Clark Coolidge, had previously been associated with Angel Hair Books. Both presses were dependent on sales-generated income combined with the support offered by grants and awards. Warsh was a recipient of National Endowment for the Arts grants in 1966 and 1979, and he received a Coordinating Council of Literary Magazines award in 1981.\",\"subnote_guid\":\"831a437650bffa845074f01c3168dfaa\"}],\"type\":\"bioghist\",\"persistent_id\":\"aspace_67bca41f9ab6477c38c9784f0df59929\",\"label\":\"Historical Background\"}','admin','admin','2016-08-24 13:24:15','2016-08-24 13:24:15','2016-08-24 13:24:15',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(72,1,4,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":false,\"jsonmodel_type\":\"note_text\",\"content\":\"Not Available\",\"subnote_guid\":\"ed467624bd79b0cdd18f6b5badb79e3e\"}],\"type\":\"acqinfo\",\"persistent_id\":\"aspace_5f8369bab637229e14466aa76a5ea41d\",\"label\":\"Acquisition Information\"}','admin','admin','2016-08-24 13:24:15','2016-08-24 13:24:15','2016-08-24 13:24:15',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(73,1,4,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":false,\"jsonmodel_type\":\"note_text\",\"content\":\"Publication rights are held by the creator of the collection.\",\"subnote_guid\":\"c9978369fc24ea206fa207f0d9789100\"}],\"type\":\"userestrict\",\"persistent_id\":\"aspace_924f23439a86089f98da99e10d1bf91b\",\"label\":\"Publication Rights\"}','admin','admin','2016-08-24 13:24:15','2016-08-24 13:24:15','2016-08-24 13:24:15',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(74,1,4,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":false,\"jsonmodel_type\":\"note_text\",\"content\":\"Collection is open for research.\",\"subnote_guid\":\"e7cde1949d70eae50a6184ca0449aabd\"}],\"type\":\"accessrestrict\",\"persistent_id\":\"aspace_a3598097532c44384b78f197801f8fbf\",\"label\":\"Access\"}','admin','admin','2016-08-24 13:24:15','2016-08-24 13:24:15','2016-08-24 13:24:15',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(75,1,4,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":false,\"jsonmodel_type\":\"note_text\",\"content\":\"United Artists (New York, N.Y.) Records, MSS 0012. Mandeville Special Collections Library, UCSD.\",\"subnote_guid\":\"40ea5c16a933b39665fa4fc3a47579a8\"}],\"type\":\"prefercite\",\"persistent_id\":\"aspace_940d38a27f412476986bc0ca80e87f59\",\"label\":\"Preferred Citation\"}','admin','admin','2016-08-24 13:24:15','2016-08-24 13:24:15','2016-08-24 13:24:15',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(76,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_langmaterial\",\"content\":[\"English\"],\"type\":\"langmaterial\",\"persistent_id\":\"3cf624e8f28183f60e62e76267c63652\"}','admin','admin','2016-08-24 13:26:49','2016-08-24 13:26:49','2016-08-24 13:26:49',NULL,NULL,47,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(77,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_langmaterial\",\"content\":[\"English\"],\"type\":\"langmaterial\",\"persistent_id\":\"aspace_07d91fa6e22f7a85f194cb5c4ed96e5a\"}','admin','admin','2016-08-24 13:26:49','2016-08-24 13:26:49','2016-08-24 13:26:49',NULL,NULL,48,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(78,1,5,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"The collection comprises seven laboratory notebooks documenting Szilard\'s and Novick\'s investigations of bacteria and viruses, correspondence between the two scientist from 1948 to 1964, and photographs of the chemostat they used for their work.\",\"subnote_guid\":\"f5d5885f4cf569b3522b8863fd2fa76d\"}],\"type\":\"odd\",\"persistent_id\":\"aspace_de94026a3de3eb86cef5d4903aee587d\",\"label\":\"Summary\"}','admin','admin','2016-08-24 13:26:49','2016-08-24 13:26:49','2016-08-24 13:26:49',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(79,1,5,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"Leo Szilard was a nuclear physicist, biologist and advocate of global arms control. Aaron Novick is a biophysicist. From 1948 to 1952, they jointly investigated the genetics and physiology of bacteria and viruses at the Institute of Radiology and Physics (University of Chicago).\",\"subnote_guid\":\"ac5cfc3e9b63ee5b5742d122e81a94d8\"}],\"type\":\"bioghist\",\"persistent_id\":\"aspace_e4e304de0375e8d95400cedc29fb5aa3\",\"label\":\"Biographical / Historical\"}','admin','admin','2016-08-24 13:26:49','2016-08-24 13:26:49','2016-08-24 13:26:49',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(80,1,5,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"Date of acquisition--1991.\",\"subnote_guid\":\"460db1acf00a2478db3111e5ca4debec\"}],\"type\":\"acqinfo\",\"persistent_id\":\"aspace_ee118f02248e8367cfba69bcbfed8173\",\"label\":\"Immediate Source of Acquisition\"}','admin','admin','2016-08-24 13:26:49','2016-08-24 13:26:49','2016-08-24 13:26:49',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(81,1,5,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"Arranged in. three series: 1. <emph>Correspondence</emph>. 2. Laboratory notebooks. 3. <emph>Photographs</emph>\",\"subnote_guid\":\"8f96d08c5fa0b907bb290144c5257c9c\"}],\"type\":\"arrangement\",\"persistent_id\":\"aspace_145f306cd940892dc39cf67ae9cfe5b6\",\"label\":\"Arrangement\"}','admin','admin','2016-08-24 13:26:49','2016-08-24 13:26:49','2016-08-24 13:26:49',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(82,1,5,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"The collection is open for research.\",\"subnote_guid\":\"77f790e1170dd2d85d9855963b719095\"}],\"type\":\"accessrestrict\",\"persistent_id\":\"aspace_d88b7436ff4e6488b2ccb716afacdd8e\",\"label\":\"Conditions Governing Access\"}','admin','admin','2016-08-24 13:26:49','2016-08-24 13:26:49','2016-08-24 13:26:49',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(83,1,5,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"js