),(2264,1,NULL,1952,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"Rush reports that he was driven to Rosehill to visit their son, Ben, and also met neighbors. He figures that two-fifths of all those sent to Bush Hill hospital have died, because his remedies were not used.\",\"subnote_guid\":\"a6e79e9df6408ed672e5b024c1fe5a6b\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_efbab2a35ef3def1eaa6d352885624ea\",\"label\":\"Scope and Contents\"}','noahh','noahh','2019-09-25 01:14:52','2019-09-25 01:14:52','2019-09-25 01:14:52',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(2265,1,NULL,1953,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_singlepart\",\"content\":[\"3 pages; 23 cm\"],\"type\":\"physdesc\",\"persistent_id\":\"aspace_34dc4a2f0bf1e0750dd378a698e4c047\"}','noahh','noahh','2019-09-25 01:14:52','2019-09-25 01:14:52','2019-09-25 01:14:52',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(2266,1,NULL,1953,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"Gift of Josiah Charles Trent Collection, 1956\",\"subnote_guid\":\"d6413ad4923aa812f6c227b7a5356fc9\"}],\"type\":\"acqinfo\",\"persistent_id\":\"aspace_73addcd96dac3dd80820b4d8999ab366\",\"label\":\"Immediate Source of Acquisition\"}','noahh','noahh','2019-09-25 01:14:52','2019-09-25 01:14:52','2019-09-25 01:14:52',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(2267,1,NULL,1953,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"2-page transcript available\",\"subnote_guid\":\"c4b7b9fb19e1bb17a0980b3c8cf14f11\"}],\"type\":\"altformavail\",\"persistent_id\":\"aspace_36f6b31727f12f6b6d0c50b6a54f67ce\",\"label\":\"Existence and Location of Copies\